const arr = msg.payload;
if (!Array.isArray(arr) || arr.length === 0) return null;

function canonRef(ref) {
  return String(ref || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
}

const m = {};
for (const r of arr) {
  const rawId = String(r.ID || "").trim();
  const id = canonRef(rawId);
  const lat = Number(r.Latitude);
  const lon = Number(r.Longitude);
  const name = String(r.Name || "").trim();

  if (!id) continue;
  if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

  m[id] = { lat, lon, name, rawId };
}

global.set("wwff_loc", m);

node.status({
  fill: "green",
  shape: "dot",
  text: `WWFF loc cached: ${Object.keys(m).length}`
});

return null;

const spots = msg.payload;
if (!Array.isArray(spots) || spots.length === 0) return null;

const out = [];
for (const s of spots) {
  if (!s) continue;
  const ref = String(s.reference || "").trim().toUpperCase();
  const activator = String(s.activator || "").trim().toUpperCase();
  const mode = String(s.mode || "").trim().toUpperCase();
  const freq = Number(s.frequency_khz);
  const lat = Number(s.latitude);
  const lon = Number(s.longitude);
  const t = Number(s.spot_time);
  const refName = String(s.reference_name || "").trim();
  const remarks = String(s.remarks || "").trim();

  if (!ref || !Number.isFinite(t)) continue;

  out.push({
    source: "wwff",
    id: Number(s.id) || t,
    reference: ref,
    reference_name: refName,
    activator,
    mode,
    frequency_khz: Number.isFinite(freq) ? freq : null,
    latitude: Number.isFinite(lat) ? lat : null,
    longitude: Number.isFinite(lon) ? lon : null,
    spot_time: t,
    remarks
  });
}

return out.length ? [{ payload: out }] : null;

const arr = msg.payload;
if (!Array.isArray(arr) || arr.length === 0) return null;

const out = [];
for (const r of arr) {
  if (!r) continue;
  const ref = String(r.WWFFid || r.actSite || r.actLocation || "").trim().toUpperCase();
  const activator = String(r.actCallsign || "").trim().toUpperCase();
  const mode = String(r.actMode || r.mode || "").trim().toUpperCase();
  const freqMHz = Number(r.actFreq || r.freq);
  const freq_khz = Number.isFinite(freqMHz) ? Math.round(freqMHz * 1000) : null;

  const tStr = String(r.actTime || "").trim();
  let spot_time = null;
  if (tStr) {
    const d = new Date(tStr.replace(' ', 'T') + 'Z');
    if (!isNaN(d.getTime())) spot_time = Math.floor(d.getTime() / 1000);
  }
  if (!spot_time) {
    const idNum = Number(r.actID);
    spot_time = Number.isFinite(idNum) ? idNum : Math.floor(Date.now() / 1000);
  }

  const remarks = String(r.actComments || r.remarks || "").trim();
  const refName = String(r.actLocation || r.reference_name || "").trim();

  if (!ref) continue;

  out.push({
    source: "parksnpeaks",
    id: String(r.actID || spot_time),
    reference: ref,
    reference_name: refName,
    activator,
    mode,
    frequency_khz: freq_khz,
    latitude: null,
    longitude: null,
    spot_time,
    remarks
  });
}

return out.length ? [{ payload: out }] : null;

const items = msg.payload;
if (!Array.isArray(items) || items.length === 0) return null;

const loc = global.get("wwff_loc") || {};

const DEDUPE_WINDOW = 5 * 60;
const nowSec = Math.floor(Date.now() / 1000);

let seen = context.get("seen") || {};

function clean(s) {
  return String(s || "").trim().replace(/\s+/g, " ");
}

function canonRef(ref) {
  return String(ref || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
}

function makeKey(it) {
  const refKey = canonRef(it.reference);
  const act = clean(it.activator).toUpperCase();
  const mode = clean(it.mode).toUpperCase();
  const f = it.frequency_khz ? String(it.frequency_khz) : "";
  const bucket = Math.floor(Number(it.spot_time || nowSec) / 120);
  return `${refKey}|${act}|${mode}|${f}|${bucket}`;
}

for (const k of Object.keys(seen)) {
  if ((nowSec - seen[k]) > (DEDUPE_WINDOW * 3)) delete seen[k];
}

const out = [];
for (const it of items) {
  const refRaw = clean(it.reference);
  const refKey = canonRef(refRaw);
  if (!refKey) continue;

  let lat = Number(it.latitude);
  let lon = Number(it.longitude);

  if (Number.isFinite(lat) && Number.isFinite(lon) && Math.abs(lat) < 0.0001 && Math.abs(lon) < 0.0001) {
    lat = NaN;
    lon = NaN;
  }

  if (!Number.isFinite(lat) || !Number.isFinite(lon)) {
    const rec = loc[refKey];
    if (rec && Number.isFinite(rec.lat) && Number.isFinite(rec.lon)) {
      lat = rec.lat;
      lon = rec.lon;
      it.reference_name = clean(it.reference_name) || clean(rec.name);
    }
  }

  if (!Number.isFinite(lat) || !Number.isFinite(lon)) continue;

  it.reference = refRaw;
  it.reference_key = refKey;
  it.latitude = lat;
  it.longitude = lon;

  const key = makeKey(it);
  const last = seen[key] || 0;
  if ((nowSec - last) < DEDUPE_WINDOW) continue;

  seen[key] = nowSec;
  out.push(it);
}

context.set("seen", seen);

return out.length ? out.map(x => ({ payload: x })) : null;

const APRS_CALLSIGN = "YOUR_CALLSIGN";

const SYMBOL_TABLE = "\\";
const SYMBOL_CODE  = ";";

const MIN_TX_INTERVAL = 10 * 60;

function clean(s) {
  return String(s || "").trim().replace(/\s+/g, " ");
}

function canonRef(ref) {
  return String(ref || "").trim().toUpperCase().replace(/[^A-Z0-9]/g, "");
}

function objName9(ref) {
  const t = canonRef(ref);
  return (t + "         ").slice(0, 9);
}

function pad2(n) { return String(n).padStart(2, "0"); }

function formatLat(lat) {
  const hemi = lat < 0 ? "S" : "N";
  const a = Math.abs(lat);
  const deg = Math.floor(a);
  const min = (a - deg) * 60;
  const mm = Math.floor(min);
  const hh = Math.floor((min - mm) * 100);
  return pad2(deg) + pad2(mm) + "." + pad2(hh) + hemi;
}

function formatLon(lon) {
  const hemi = lon < 0 ? "W" : "E";
  const a = Math.abs(lon);
  const deg = Math.floor(a);
  const min = (a - deg) * 60;
  const mm = Math.floor(min);
  const hh = Math.floor((min - mm) * 100);
  return String(deg).padStart(3, "0") + pad2(mm) + "." + pad2(hh) + hemi;
}

function zuluStamp(nowSec) {
  const d = new Date(nowSec * 1000);
  return pad2(d.getUTCDate()) + pad2(d.getUTCHours()) + pad2(d.getUTCMinutes()) + "z";
}

function truncate(s, maxLen) {
  const t = clean(s);
  return t.length <= maxLen ? t : t.slice(0, maxLen);
}

const s = msg.payload;
if (!s) return null;

const refKey = canonRef(s.reference);
if (!refKey) return null;

let lat = Number(s.latitude);
let lon = Number(s.longitude);

if (!Number.isFinite(lat) || !Number.isFinite(lon) || (Math.abs(lat) < 0.0001 && Math.abs(lon) < 0.0001)) {
  return null;
}

const nowSec = Math.floor(Date.now() / 1000);
let tx = context.get("tx") || {};

const lastTx = tx[refKey] || 0;
if ((nowSec - lastTx) < MIN_TX_INTERVAL) return null;

const activator = clean(s.activator).toUpperCase();
const mode = clean(s.mode).toUpperCase();
const freq = s.frequency_khz ? String(s.frequency_khz) : "";
const refName = clean(s.reference_name);

let comment = `${activator} ${freq} ${mode} ${clean(s.reference)}`.trim();
if (refName) comment += `, ${refName}`;
comment = truncate(comment, 70);

const obj9 = objName9(s.reference);
const ts = zuluStamp(nowSec);
const latStr = formatLat(lat);
const lonStr = formatLon(lon);

const info = `;${obj9}*${ts}${latStr}${SYMBOL_TABLE}${lonStr}${SYMBOL_CODE}${comment}`;

msg.payload = `${APRS_CALLSIGN}>APRS,TCPIP*:${info}\r\n`;

tx[refKey] = nowSec;
context.set("tx", tx);

node.status({ fill: "green", shape: "dot", text: `TX ${refKey}` });
return msg;

const APRS_CALLSIGN = "YOUR_CALLSIGN";
const APRS_PASS = "YOUR_APRS_PASSCODE";
const APRS_VERS = "NR-WWFF 1.0";
const APRS_FILTER = "filter r/0/0/999";

const t = (msg.status && msg.status.text) ? String(msg.status.text).toLowerCase() : "";

if (t.includes("disconnected")) {
  context.set("sentLogin", false);
  return null;
}

if (!t.includes("connected")) return null;

if (context.get("sentLogin") === true) return null;
context.set("sentLogin", true);

msg.payload = `user ${APRS_CALLSIGN} pass ${APRS_PASS} vers ${APRS_VERS} ${APRS_FILTER}\r\n`;
return msg;
